{
  "name": "oribiserv-customer-portal",
  "version": "1.0.0",
  "description": "Customer portal for Oribiserv clients to manage accounts and internet services.",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "dev": "node server.js"
  },
  "dependencies": {
    "express": "^4.18.2"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "author": "Oribiserv",
  "license": "MIT"
}

const express = require('express');
const path = require('path');
const app = express();

// Use the PORT environment variable provided by the host, or default to 3000
const PORT = process.env.PORT || 3000;

/**
 * Serve static files from the root directory.
 * This allows the browser to fetch index.tsx, styles, and other assets.
 */
app.use(express.static(__dirname));

/**
 * Handle Single Page Application (SPA) routing.
 * If a request doesn't match a static file, serve index.html.
 * This ensures that routes like /support or /balance work on page refresh.
 */
app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, 'index.html'));
});

app.listen(PORT, () => {
  console.log('-------------------------------------------');
  console.log('Oribiserv Portal is running!');
  console.log(`Local: http://localhost:${PORT}`);
  console.log('-------------------------------------------');
});
